pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // --- 1. Residual contribution -------------------------------------------------
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    let mut score = 0.9 * post_residual as f64; // baseline proportional to free space

    // small gaps are sometimes desirable for tight packing
    if post_residual <= 5 {
        score -= 0.7;
    }

    // penalize very large gaps
    if post_residual > 70 {
        score += 0.004 * (post_residual as f64 - 70.0).powi(2);
    }

    // --- 2. Look‑ahead with next item ---------------------------------------------
    if post_residual >= next_item_size {
        // good fit, reward a comfortable margin
        score += 1.8 * ((post_residual - next_item_size) as f64).sqrt();
    } else {
        // gap too tight, penalise
        score += 3.5 * ((next_item_size - post_residual) as f64).sqrt();
    }

    // --- 3. Open‑bin pressure ------------------------------------------------------
    score += 0.35 * open_bins_count as f64;
    if open_bins_count > 12 {
        score += 6.0;
    }

    // --- 4. Fitting‑bins incentive --------------------------------------------------
    if fitting_bins_count >= 6 {
        score -= 2.2;
    } else if fitting_bins_count == 1 {
        score -= 3.8;
    }
    // additional soft reward for many fitting bins
    score -= (fitting_bins_count as f64).powi(2) * 0.015;

    // --- 5. New‑bin handling --------------------------------------------------------
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // grow sub‑linearly with more bins
        score += 2.4 * (open_bins_count as f64).powf(0.55);
    }

    // --- 6. Mean‑residual alignment -------------------------------------------------
    let mean_ratio = mean_residual / bin_capacity as f64;
    let diff_ratio = (residual_ratio - mean_ratio).abs();
    if diff_ratio > 0.12 {
        score += diff_ratio * 22.0;
    } else {
        score -= 0.35;
    }

    // item‑size synergy: large items with very small residuals are undesirable
    if item_size > bin_capacity / 2 && post_residual < (bin_capacity / 4) {
        score += 2.5;
    }

    // --- 7. Progress‑based relaxation ----------------------------------------------
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress).powi(2) * 1.6;

    score
}

