pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base: penalize the amount of unused space after placement
    let mut score = 0.6 * post_residual as f64;

    // Highly desirable tiny gaps
    if post_residual <= 3 {
        score -= 4.0;
    } else if post_residual <= 6 {
        score -= 2.0;
    } else if post_residual <= 10 {
        score -= 0.5;
    }

    // Quadratic penalty for large gaps
    if post_residual > 70 {
        let excess = post_residual - 70;
        score += 0.003 * (excess as f64).powi(2);
    }

    // Residual ratio bonus/penalty
    let ratio = post_residual as f64 / bin_capacity as f64;
    if ratio > 0.75 {
        score += 10.0 * (ratio - 0.75);
    } else if ratio < 0.20 {
        score -= 5.0 * (0.20 - ratio);
    }

    // Look‑ahead: prefer bins that leave a residual close to the next item
    if next_item_size > post_residual {
        score += 4.0 * (next_item_size - post_residual) as f64;
    } else {
        score -= 0.9 * (next_item_size as f64 - post_residual as f64).abs();
    }

    // Align with the mean residual
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    if mean_diff < 3.0 {
        score -= 2.0;
    } else {
        score += 0.015 * mean_diff;
    }

    // Pressure from many open bins: encourage using bins that can fit many items,
    // but penalise an excessive open‑bin count.
    if fitting_bins_count >= 5 {
        score -= 3.0;
    } else if fitting_bins_count == 1 {
        score -= 4.0;
    }
    score += 0.3 * open_bins_count as f64;
    if open_bins_count > 15 {
        score += 5.0;
    }

    // New‑bin handling: only open a new bin when the current bins are truly poor fits
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 3.0; // first bin is always worth it
        } else {
            score += 1.5 * (open_bins_count as f64).sqrt(); // slight penalty that grows
        }
    }

    // Progress‑based relaxation
    let progress = step_index as f64 / total_items as f64;
    if progress < 0.25 {
        score += 1.0;
    } else if progress > 0.85 {
        score -= 0.5;
    } else {
        score += (1.0 - progress) * 0.5;
    }

    // Small adjustment for very large streams: loosen penalties for large residuals
    if total_items > 10_000 && post_residual > 80 {
        score -= 1.0;
    }

    score
}

