pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score: the residual after placing the item
    let mut score = post_residual as f64;

    // ------------------------------------------------------------------
    // 1. Gap‑sensitivity: heavily penalise gaps that cannot accommodate the
    //    next item, but also reward large gaps when the next item is very
    //    large (look‑ahead).
    // ------------------------------------------------------------------
    if post_residual < next_item_size {
        // Gap too small – add a linear penalty amplified by 4.0
        score += (next_item_size - post_residual) as f64 * 4.0;
    } else if next_item_size > 80 && post_residual < 20 {
        // Next item is huge but we still have a small gap – discourage this bin
        score += 15.0;
    }

    // Very small residuals are usually a waste of space
    if post_residual < 5 {
        score += 8.0;
    }

    // ------------------------------------------------------------------
    // 2. Open‑bin pressure: keep the number of partially filled bins
    //    low, but be generous when many bins are already open.
    // ------------------------------------------------------------------
    score += 0.3 * open_bins_count as f64;
    if open_bins_count > 10 {
        score += 5.0;
    }

    // ------------------------------------------------------------------
    // 3. Fitting‑bins incentive: if many bins can fit the item, prefer them.
    // ------------------------------------------------------------------
    if fitting_bins_count > 5 {
        score -= 2.0;
    }
    if fitting_bins_count == 1 {
        score -= 4.0;
    }

    // ------------------------------------------------------------------
    // 4. New‑bin handling: penalise opening a fresh bin unless there
    //    are no other options.
    // ------------------------------------------------------------------
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 2.0 * open_bins_count as f64;
    }

    // ------------------------------------------------------------------
    // 5. Mean‑residual alignment: prefer bins whose residual is close to
    //    the global mean.
    // ------------------------------------------------------------------
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    if mean_diff > 5.0 {
        // The farther from the mean, the higher the penalty
        score += mean_diff * 0.05;
    } else {
        // Slight reward for being close to the mean
        score -= 0.5;
    }

    // ------------------------------------------------------------------
    // 6. Large residual quadratic penalty: discourage very large gaps.
    // ------------------------------------------------------------------
    if post_residual > 30 {
        score += 0.001 * (post_residual as f64).powi(2);
    }

    // ------------------------------------------------------------------
    // 7. Progress‑based relaxation: towards the end we tolerate
    //    partially filled bins more.
    // ------------------------------------------------------------------
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * 1.5;

    score
}

